import{z as B,x as i,o as r,c as p,q as o,j as s,D as e,d as t,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"拓扑排序","description":"","frontmatter":{"title":"拓扑排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/topo-sort.md","filePath":"cs/topo-sort.md","lastUpdated":1791063341000}'),d={name:"cs/topo-sort.md"};function h(D,a,u,f,F,m){const A=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="拓扑排序" tabindex="-1">拓扑排序 <a class="header-anchor" href="#拓扑排序" aria-label="Permalink to &quot;拓扑排序&quot;">​</a></h1><div class="epigraph"><p>无环有向图的顶点可以排成一线，使得每条边都从左指向右。</p><footer>—— 据 Kahn, Topological Sorting of Large Networks, 1962；CLRS 第 22.4 节整理</footer></div><p>上一课<a href="/cs/bcc-bridge">连通分量与桥</a>证明：有向环当且仅当有反向边。<a href="/cs/dag-repr">DAG 与拓扑序预备</a>已说明无环才能线性化。本课不重证无环。缺口是：<strong>算法</strong>——给出一个合法顶点序，或报告不可能。本课只交出按完成时刻降序，以及 Kahn 的入度为零队列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务依赖、编译的符号、包安装，边 \\(u\\to v\\) 表示 \\(u\\) 先于 \\(v\\)。需要一条总序尊重全部边。有环则不存在。缺口不是再定义 DAG，而是从邻接表在 \\(\\Theta(V+E)\\) 内产出序。</p><p><span class="marginnote">直觉类比：拓扑序像排选课顺序，「先修」箭头全指向右。只要课表里没有互为先修的环，总能排出一份一学期接一学期读下去的清单；一旦出现环（A 的先修是 B、B 的先修是 A），这门课永远开不了。</span></p><p>DFS 法：做一遍 DFS，按 \\(u.f\\) 降序输出。正确性：若有边 \\(u\\to v\\)，则 \\(v.f\\lt u.f\\)（否则 \\(u\\to v\\) 会是反向边，与 DAG 矛盾）。Kahn：反复取入度 \\(0\\) 的点，删出边；若结束时还有点，则有环。</p><h3 id="拓扑序不是唯一的最短路" tabindex="-1">拓扑序不是唯一的最短路 <a class="header-anchor" href="#拓扑序不是唯一的最短路" aria-label="Permalink to &quot;拓扑序不是唯一的最短路&quot;">​</a></h3><p>同一 DAG 可以有许多拓扑序。BFS 层序不是拓扑序，除非图碰巧是按层编号的。也不要把拓扑序当成加权最短路：那是后课在 DAG 上按拓扑松弛，本课只给序。</p><p><span class="marginnote">Kahn 1962 用入度；CLRS 用 DFS 完成时刻。两者等价于「存在且仅当无环」。并查集课已有的结构这里用不上：环检测走 DFS 或入度，不走连通分量的误用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任选其一。DFS 完成后倒序写表。Kahn 用<a href="/cs/queue-buffer">队列</a>存当前零入度点。输出长度小于 \\(|V|\\) 则失败。</p>',12)),(r(),s(n,null,{default:e(()=>[l(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%9C%89%E5%90%91%E5%9B%BE%22%5D%20--%3E%20DFS%5B%22DFS%20%E5%AE%8C%E6%88%90%E6%97%B6%E5%88%BB%E9%99%8D%E5%BA%8F%22%5D%0A%20%20G%20--%3E%20KAHN%5B%22%E5%8F%8D%E5%A4%8D%E5%8F%96%E5%85%A5%E5%BA%A6%200%22%5D%0A%20%20DFS%20--%3E%20ORD%5B%22%E6%8B%93%E6%89%91%E5%BA%8F%E6%88%96%E6%8A%A5%E7%8E%AF%22%5D%0A%20%20KAHN%20--%3E%20ORD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("a",{href:"/cs/sparse-graph"},"稀疏图"),t("用邻接表；每次边只降一次入度。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"序一旦给出，后课可按序做动态规划或松弛：到 \\(v\\) 时全部前驱已处理。这是 DAG 最短路、最长路的共同前置，本课不把松弛写进来。编译课的依赖仍是同一对象：通行证之间的边若成环则无法排程。",-1)),a[6]||(a[6]=E("p",null,"多个零入度点时 Kahn 的队列次序决定哪一个合法序；那是平局，不是错误。",-1)),(r(),s(n,null,{default:e(()=>[l(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%85%88%E6%89%AB%E4%B8%80%E9%81%8D%2C%E7%AE%97%E5%87%BA%E6%AF%8F%E4%B8%AA%E7%82%B9%E7%9A%84%E5%85%A5%E5%BA%A6%22%5D%20--%3E%20Q%5B%22%E5%85%A5%E5%BA%A6%E4%B8%BA%200%20%E7%9A%84%E7%82%B9%E8%BF%9B%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20T%5B%22%E5%8F%96%E5%87%BA%E9%98%9F%E9%A6%96%2C%E5%86%99%E5%85%A5%E7%BB%93%E6%9E%9C%22%5D%0A%20%20T%20--%3E%20D%5B%22%E5%88%A0%E5%AE%83%E7%9A%84%E5%87%BA%E8%BE%B9%3A%E5%90%8E%E7%BB%A7%E5%85%A5%E5%BA%A6%E5%90%84%E5%87%8F%201%22%5D%0A%20%20D%20--%3E%20Z%7B%22%E6%9C%89%E5%90%8E%E7%BB%A7%E5%85%A5%E5%BA%A6%E5%8F%98%200%3F%22%7D%0A%20%20Z%20--%3E%7C%22%E6%98%AF%22%7C%20Q%0A%20%20Z%20--%3E%7C%22%E5%90%A6%22%7C%20E%7B%22%E9%98%9F%E5%88%97%E7%A9%BA%E4%BA%86%E8%BF%98%E6%9C%89%E7%82%B9%E6%B2%A1%E8%BE%93%E5%87%BA%3F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20CYC%5B%22%E6%8A%A5%E5%91%8A%E6%9C%89%E7%8E%AF%2C%E6%97%A0%E6%8B%93%E6%89%91%E5%BA%8F%22%5D%0A%20%20E%20--%3E%7C%22%E5%85%A8%E9%83%A8%E8%BE%93%E5%87%BA%22%7C%20OK%5B%22%E7%BB%93%E6%9E%9C%E5%B0%B1%E6%98%AF%E4%B8%80%E6%9D%A1%E5%90%88%E6%B3%95%E6%8B%93%E6%89%91%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：5 个点、7 条边的小图，Kahn 先扫邻接表算入度，再把零入度点入队；每条边恰好被删一次、每个点恰好入队一次，总工作量是 \\(V+E=10\\) 的常数倍——\\(\\Theta(V+E)\\) 就是这么数出来的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理带权边。不写强连通分量缩点后再拓扑——那是把有环图缩成 DAG 的后话。无向图没有拓扑序这一定义。偏序的线性扩张在组合里更一般，本课只做有向图上的算法。</p><p>后课默认：DAG 上有 \\(\\Theta(V+E)\\) 拓扑序；有环则算法报告失败。正权最短路下一课从另一端（非负权一般图）进入。</p><p><span class="marginnote">常见误区：以为拓扑序唯一。同一个 DAG 往往有大量合法序——多个零入度点时取哪个都对，那是平局不是错误；需要确定性输出时，才额外规定按字典序等规则打破平局。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAG 上拓扑序存在；DFS 完成降序或 Kahn 入度均可。</li><li>有向环则失败；代价 \\(\\Theta(V+E)\\)。</li><li>序不唯一；本课不给最短路。</li><li>出处：Kahn, 1962；CLRS 第 22.4 节。</li></ul>',7))])}const S=B(d,[["render",h]]);export{C as __pageData,S as default};
